113	    /** Move a claim to another status; a change its status does not allow, or of a claim dated in a closed
114	     * period, is refused. A settle by a clerk of a claim whose due is above the clerk limit sends it PENDING a
115	     * steward instead. */
116	    @Transactional
117	    public Claim changeStatus(String user, String sheetId, Long id, ClaimStatus next) {
118	        sheets.today(sheetId); // the sheet must exist
119	        // Locking the sheet before taking the number opens claims one at a time; a refused open rolls back
120	        // and gives the number back.
121	        if (next == ClaimStatus.OPEN) {
122	            sheets.lock(sheetId);
123	        }
124	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
125	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
126	        String number = next == ClaimStatus.OPEN ? nextNumber(sheetId, claim) : null;
127	        requireOpenPeriod(sheetId, claim.getDate());
128	        // A steward may void a SETTLED claim within the days allowed after it was settled.
129	        boolean unsettle = next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
130	        if (!unsettle && !claim.getStatus().canBecome(next)) {
131	            throw new ResponseStatusException(HttpStatus.CONFLICT,
132	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
133	        }
134	        if (unsettle) {
135	            requireVoidableSettled(user, sheetId, claim);
136	        } else {
137	            // Only a role the sheet's permission matrix allows may open, settle or void a claim.
138	            settings.requirePermitted(sheetId, user, PERMISSIONS.get(next));
139	        }
140	        // A deferred claim cannot be settled until the sheet's today reaches the date it is deferred until.
141	        if (next == ClaimStatus.SETTLED && claim.deferredOn(sheets.today(sheetId))) {
142	            throw new ResponseStatusException(HttpStatus.CONFLICT,
143	                    "The claim is deferred until " + claim.getDeferredUntil() + ".");
144	        }
145	        // Four eyes: whoever opened a claim cannot also settle it.
146	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
147	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it.");
148	        }
149	        Person person = requirePerson(sheetId, claim.getPersonId());
150	        BigDecimal due = rollup.dueOf(claim, person);
151	        // A claim whose due is above the proof threshold in force on its date needs a proof before it is settled,
152	        // whoever settles it, so it never goes PENDING without one.
153	        if (next == ClaimStatus.SETTLED) {
154	            settings.requireProof(sheetId, claim.getDate(), due, claim.getProofs());
155	        }
156	        // A clerk settles only a claim whose due is within the sheet's clerk limit; above it, a steward must
157	        // approve it.
158	        if (next == ClaimStatus.SETTLED && !settings.maySettle(sheetId, user, due)) {
159	            next = ClaimStatus.PENDING;
160	        }
161	        Snapshot before = rollup.snapshot(sheetId);
162	        claim.setStatus(next);
163	        if (next == ClaimStatus.OPEN) {
164	            claim.setNumber(number);
165	            claim.setOpenedBy(user);
166	        }
167	        // A voided claim's line carries the number it had.
168	        String entry = entry(EVENTS.get(next), user, person, claim);
169	        if (unsettle) {
170	            // The frozen figure leaves every total; the claim keeps it, and its number.
171	            entry += " reversed=" + figure(claim.getSettledDue());
172	        }
173	        if (next == ClaimStatus.SETTLED) {
174	            // Settling fixes the due at the figure the claim has: the one its last statement bound it to, else
175	            // the rate its grade has on its date; with no figure it stays live. The late charge it has (taken
176	            // while it is still OPEN) is frozen in.
177	            entry += settle(claim, due);
178	        }
179	        logStatus(user, sheets.today(sheetId), claim, person);
180	        claims.flush();
181	        audit.recordOnCommit(entry);
182	        if (next == ClaimStatus.SETTLED) {
183	            notifyWatchers(user, person, claim);
184	        }
185	        rollup.recordChanges(user, sheetId, before);
186	        return claim;
187	    }
