295	    /** Split an amount off an OPEN claim: more than 0.00 and less than its amount. The claim keeps the rest and
296	     * loses any figure a statement bound it to; a new OPEN claim of the amount split off, with the same date and
297	     * note, takes the next number, is opened by the user, has its due-by fixed now from the terms in force on the
298	     * date, and names the claim it was split from. A claim that is not OPEN (PENDING, settled, ...), is deferred,
299	     * or is dated in a closed period, is refused. */
300	    @Transactional
301	    public Split split(String user, String sheetId, Long id, BigDecimal amount) {
302	        LocalDate today = sheets.today(sheetId);
303	        // Locking the sheet before taking the number numbers claims one at a time; a refused split rolls back and
304	        // gives the number back.
305	        sheets.lock(sheetId);
306	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
307	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
308	        requireOpenPeriod(sheetId, claim.getDate());
309	        if (claim.getStatus() != ClaimStatus.OPEN) {
310	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only an OPEN claim can be split.");
311	        }
312	        if (claim.deferredOn(today)) {
313	            throw new ResponseStatusException(HttpStatus.CONFLICT,
314	                    "The claim is deferred until " + claim.getDeferredUntil() + ".");
315	        }
316	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
317	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
318	                    "The amount split off is more than 0.00 and less than the claim's amount.");
319	        }
320	        Person person = requirePerson(sheetId, claim.getPersonId());
321	        Snapshot before = rollup.snapshot(sheetId);
322	        claim.setAmount(claim.getAmount().subtract(amount));
323	        claim.unbind();
324	        LocalDate dated = claim.getDate();
325	        LocalDate dueBy = dueBy(sheetId, person, dated);
326	        Claim fresh = new Claim(sheetId, person.getId(), amount, dated, dueBy, claim.getNote());
327	        fresh.setSplitFrom(claim.getNumber());
328	        fresh.setStatus(ClaimStatus.OPEN);
329	        fresh.setNumber(nextNumber(sheetId, fresh));
330	        fresh.setOpenedBy(user);
331	        Claim split = claims.saveAndFlush(fresh);
332	        logStatus(user, today, split, person);
333	        claims.flush();
334	        audit.recordOnCommit(entry("CLAIM_SPLIT", user, person, claim) + " into=" + split.getNumber());
335	        audit.recordOnCommit(entry("CLAIM_OPENED", user, person, split));
336	        rollup.recordChanges(user, sheetId, before);
337	        return new Split(claim, split);
338	    }
