362	    /** A steward rejects a PENDING claim with a reason: it is OPEN again, bound again by its person's last
363	     * statement if that statement included it. */
364	    @Transactional
365	    public Claim reject(String user, String sheetId, Long id, String reason) {
366	        Claim claim = requirePending(user, sheetId, id);
367	        Person person = requirePerson(sheetId, claim.getPersonId());
368	        Snapshot before = rollup.snapshot(sheetId);
369	        claim.setStatus(ClaimStatus.OPEN);
