377	    /** A user whose role may reassign (a steward by the standing rule) moves a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number and
378	     * date but loses any figure a statement bound it to: it is live again until its new person's next statement.
379	     * One dated in a closed period, a correction (which names a settled claim of its own person), or one dated
380	     * after its new person is retired, is refused. */
381	    @Transactional
382	    public Claim reassign(String user, String sheetId, Long id, Long toPersonId) {
383	        sheets.today(sheetId); // the sheet must exist
384	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
385	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
386	        settings.requirePermitted(sheetId, user, Permission.REASSIGN);
387	        requireOpenPeriod(sheetId, claim.getDate());
388	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
389	            throw new ResponseStatusException(HttpStatus.CONFLICT,
390	                    "A " + claim.getStatus() + " claim cannot be moved.");
391	        }
392	        if (claim.isCorrection()) {
393	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A correction cannot be moved.");
394	        }
395	        Person from = requirePerson(sheetId, claim.getPersonId());
396	        Person to = requirePerson(sheetId, toPersonId);
397	        if (from.getId().equals(to.getId())) {
398	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The claim is already that person's.");
399	        }
400	        if (to.retiredOn(claim.getDate())) {
401	            throw new ResponseStatusException(HttpStatus.GONE,
402	                    to.getName() + " is retired from " + to.getRetiredFrom() + ".");
403	        }
404	        Snapshot before = rollup.snapshot(sheetId);
405	        claim.setPersonId(to.getId());
406	        claim.unbind();
407	        claims.flush();
408	        audit.recordOnCommit(entry("CLAIM_REASSIGNED", user, to, claim) + " from=" + from.getName() + " to="
409	                + to.getName());
410	        rollup.recordChanges(user, sheetId, before);
411	        return claim;
412	    }
