441	     * that went through. */
442	    public record OpenedAll(int opened, int refused, List<Claim> claims) {}
443	
444	    /** Open the given claims of the sheet one at a time, in list order: people in the order they were added,
445	     * each one's claims newest first. Each is opened, and numbered, as {@link #changeStatus} would open it on its
446	     * own; one that cannot be opened (or is not on the sheet) is refused and left as it is. */
447	    public OpenedAll openAll(String user, String sheetId, List<Long> ids) {
448	        return changeAll(user, sheetId, ids, ClaimStatus.OPEN);
449	    }
450	
451	    /** Settle the given claims of the sheet one at a time, in list order, each as {@link #changeStatus} would
452	     * settle it on its own: one a clerk sends PENDING counts as settled; one that cannot be settled (or is not on
453	     * the sheet) is refused and left as it is. */
454	    public OpenedAll settleAll(String user, String sheetId, List<Long> ids) {
455	        return changeAll(user, sheetId, ids, ClaimStatus.SETTLED);
456	    }
457	
458	    /** Move the given claims to a status one at a time, in list order: people in the order they were added, each
459	     * one's claims newest first, each in its own transaction; one that is refused is left as it is. */
460	    private OpenedAll changeAll(String user, String sheetId, List<Long> ids, ClaimStatus next) {
461	        Set<Long> wanted = new HashSet<>(ids);
462	        List<Claim> chosen = transaction.execute(status -> {
463	            sheets.today(sheetId); // the sheet must exist
464	            Map<Long, Integer> personOrder = new HashMap<>();
465	            for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
466	                personOrder.put(person.getId(), personOrder.size());
467	            }
468	            return claims.findBySheetIdOrderByIdDesc(sheetId).stream()
469	                    .filter(c -> wanted.contains(c.getId()))
470	                    .sorted(Comparator.comparing((Claim c) -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE)))
471	                    .toList();
472	        });
473	        List<Claim> changed = new ArrayList<>();
474	        if (settings.roleOf(sheetId, user) == Role.VIEWER || sheets.isArchived(sheetId)) {
475	            // A viewer, or anyone on an archived sheet, changes nothing: every claim is refused.
476	            return new OpenedAll(0, wanted.size(), changed);
477	        }
478	        for (Claim claim : chosen) {
479	            try {
480	                changed.add(transaction.execute(status -> changeStatus(user, sheetId, claim.getId(), next)));
481	            } catch (ResponseStatusException refused) {
482	                // Left as it is: its transaction rolled back, writing nothing.
483	            }
484	        }
485	        return new OpenedAll(changed.size(), wanted.size() - changed.size(), changed);
486	    }
