488	    /** The sequence a claim in no period is numbered in, with period numbering. */
489	    private static final String NO_PERIOD = "X";
490	
491	    /** The action of the permission matrix each status a claim is moved to takes. */
492	    private static final Map<ClaimStatus, Permission> PERMISSIONS = Map.of(
493	            ClaimStatus.OPEN, Permission.OPEN,
494	            ClaimStatus.SETTLED, Permission.SETTLE,
495	            ClaimStatus.VOID, Permission.VOID);
496	
497	    private static final Map<ClaimStatus, String> EVENTS = Map.of(
498	            ClaimStatus.OPEN, "CLAIM_OPENED",
499	            ClaimStatus.PENDING, "CLAIM_PENDING",
500	            ClaimStatus.SETTLED, "CLAIM_SETTLED",
501	            ClaimStatus.VOID, "CLAIM_VOIDED");
502	
503	    /** The figure a claim has now: what it was settled at, else what its person's last statement bound it to,
504	     * else what is due at the rate of the grade its person has on its date; none when that is n/a. */
505	    public BigDecimal figureOf(Claim claim, Person person) {
506	        return rollup.figureOf(claim, person);
507	    }
508	
509	    /** The number a claim opened now takes: the sheet's next number or, with period numbering in force, the next
510	     * in its period's own sequence, <period name>-<n>, or X-<n> for a claim in no period. */
511	    private String nextNumber(String sheetId, Claim claim) {
512	        if (!sheets.numbersByPeriod(sheetId)) {
513	            return String.valueOf(sheets.nextClaimNumber(sheetId));
514	        }
515	        String prefix = periods.periodOf(sheetId, claim.getDate()).map(Period::getName).orElse(NO_PERIOD) + "-";
516	        int last = 0;
517	        for (Claim other : claims.findBySheetIdOrderByIdDesc(sheetId)) {
518	            String number = other.getNumber();
519	            if (number != null && number.startsWith(prefix)) {
520	                String rest = number.substring(prefix.length());
521	                if (rest.matches("\\d{1,9}")) {
522	                    last = Math.max(last, Integer.parseInt(rest));
523	                }
524	            }
525	        }
526	        return prefix + (last + 1);
527	    }
