529	    /** The number a claim of this amount corrects: none unless the amount is negative, when it must name a
530	     * SETTLED claim of the same person, or the claim is refused. */
531	    private String correctedBy(String sheetId, Long personId, BigDecimal amount, String corrects) {
532	        if (amount.signum() >= 0) {
533	            return null;
534	        }
535	        String named = corrects == null ? null : corrects.trim();
536	        boolean settled = named != null && claims.findBySheetIdAndPersonId(sheetId, personId).stream()
537	                .anyMatch(c -> named.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
538	        if (!settled) {
539	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
540	                    "A correction must name a settled claim of the same person.");
541	        }
542	        return named;
543	    }
