560	    /** The due-by fixed for a claim of the person dated {@code dated}: its date plus the person's own terms, else
561	     * the terms in force then for the grade the person has then, else the sheet's terms then. */
562	    private LocalDate dueBy(String sheetId, Person person, LocalDate dated) {
563	        Integer own = person.getTerms();
564	        return dated.plusDays(own != null ? own : settings.termsFor(sheetId, person.gradeOn(dated), dated));
565	    }
